<?php
declare(strict_types=1);
require_once __DIR__.'/fixtures/NativeBusinessOrderFixture.php';
use DigiForge\Core\Settings;
use DigiForge\Database\Tables;
use DigiForge\Orders\Repository;
use DigiForge\Portal\OrderHoldWorkflow;

/** Exact restrictive local writes, with real signed Shop 2 authority. */
final class OrderHoldWorkflowTest extends WP_UnitTestCase {
 use NativeBusinessOrderFixture;
 private array $extraRows=[];
 private int $httpCalls=0;
 private $denyHttp;
 public function setUp():void {parent::setUp();\DigiForge\Core\Activator::activate();$this->bootOrderFixture();global $wpdb;foreach([Tables::fulfillment_intents(),Tables::pod_render_evidence(),Tables::pod_authorization_packages()]as $table)$this->extraRows[$table]=$wpdb->get_results('SELECT * FROM '.$table,ARRAY_A);$this->denyHttp=function(){$this->httpCalls++;return new WP_Error('unexpected_http');};add_filter('pre_http_request',$this->denyHttp);Settings::protectProduction();}
 public function tearDown():void {remove_filter('pre_http_request',$this->denyHttp);try{global $wpdb;$wpdb->query('ROLLBACK');foreach($this->extraRows as $table=>$rows){$wpdb->query('DELETE FROM '.$table);foreach($rows as $row)$wpdb->insert($table,$row,array_fill(0,count($row),'%s'));}$this->restoreOrderFixture();self::assertSame(0,$this->httpCalls);}finally{parent::tearDown();}}
 public static function holdableStates():array {return [['RECEIVED'],['VALIDATED'],['REVIEW_REQUIRED'],['APPROVED']];}
 /** @dataProvider holdableStates */
 public function testRegisteredPreviewConfirmationHoldsOnlyExactOrderAndPreservesItsHistory(string $state):void {
  self::assertTrue(class_exists(OrderHoldWorkflow::class),'A connected restrictive local order hold is required.');$order=$this->order($state);global $wpdb;$before=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Tables::orders().' WHERE id=%d',$order),ARRAY_A);self::assertNotFalse(has_action('admin_post_'.OrderHoldWorkflow::ACTION));$body=$this->body($order);$preview=$this->invoke($body);self::assertStringContainsString('Confirm local order hold',$preview);$confirm=$this->confirmed($body,$preview);$html=$this->invoke($confirm);self::assertStringContainsString('Order placed ON_HOLD locally',$html);self::assertStringContainsString('Provider cancellation: NOT PERFORMED',$html);$after=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Tables::orders().' WHERE id=%d',$order),ARRAY_A);self::assertSame('ON_HOLD',$after['state']);self::assertSame(array_diff_key($before,array_flip(['state','updated_at'])),array_diff_key($after,array_flip(['state','updated_at'])));$readiness=(new Repository())->readinessSnapshot($order);self::assertTrue(is_wp_error($readiness)||empty($readiness['ready']));self::assertStringNotContainsString('Order placed ON_HOLD locally',$this->invoke($confirm));self::assertTrue(Settings::safety_locked());
 }
 public function testMountedHoldWorksWithRevokedProviderReviewAndPreservesAllChildBytes():void {
  self::assertTrue(class_exists(OrderHoldWorkflow::class));[$order,$children]=$this->children();$connection=new \DigiForge\POD\ScopedProviderConnection();$status=$connection->status('personalized_pod',$this->fixture->integration,'printify.connection.read');PortalAccessFixture::login($this->fixture->reviewer);PrintifyApiApprovalFixture::checked($connection->decide('personalized_pod',$this->fixture->integration,'printify.connection.read',$status['review_revision'],$status['binding_hash'],'REVOKED',wp_generate_uuid4()));$this->fixture->owner();self::assertWPError((new \DigiForge\Orders\HeldFulfillmentPreparation())->forOrder('personalized_pod',$order));$get=$_GET;try{$_GET=['df_order_id'=>(string)$order];ob_start();(new \DigiForge\Portal\OrderHeldPreparationPanel())->render('personalized_pod');$panel=(string)ob_get_clean();self::assertStringContainsString('Preview local order hold',$panel);}finally{$_GET=$get;}$body=$this->body($order);self::assertStringContainsString('Order placed ON_HOLD locally',$this->invoke($this->confirmed($body,$this->invoke($body))));global $wpdb;foreach($children as $table=>$before)self::assertSame($before,$wpdb->get_results($wpdb->prepare('SELECT * FROM '.$table.' WHERE order_id=%d ORDER BY id',$order),ARRAY_A));$ready=(new Repository())->readinessSnapshot($order);self::assertNotWPError($ready);self::assertFalse($ready['ready']);self::assertFalse($ready['checks']['order_approved']);
 }
 public function testWrongShopNonceModuleAnonymousAndStaleOrderCannotHold():void {
  self::assertTrue(class_exists(OrderHoldWorkflow::class));$order=$this->order('APPROVED');$body=$this->body($order);$confirm=$this->confirmed($body,$this->invoke($body));$wrong=$body;$wrong['shop_key']='digital';self::assertStringNotContainsString('Confirm local order hold',$this->invoke($wrong));$wrong=$confirm;$wrong['order_id']=(string)($order+1);self::assertStringContainsString('nonce',$this->invoke($wrong));global $wpdb;$wpdb->update(Tables::orders(),['external_order_reference'=>'changed-after-preview'],['id'=>$order]);self::assertStringNotContainsString('Order placed ON_HOLD locally',$this->invoke($confirm));$actor=wp_get_current_user();$actor->add_cap('manage_digiforge_orders',false);try{self::assertStringNotContainsString('Confirm local order hold',$this->invoke($body));}finally{$actor->add_cap('manage_digiforge_orders');}wp_set_current_user(0);self::assertStringNotContainsString('Order placed ON_HOLD locally',$this->invoke($confirm));self::assertSame('APPROVED',$wpdb->get_var($wpdb->prepare('SELECT state FROM '.Tables::orders().' WHERE id=%d',$order)));
 }
 public function testWriteOrCheckedAuditFailureRollsBackButConsumesAcknowledgement():void {
  self::assertTrue(class_exists(OrderHoldWorkflow::class));foreach(['order','audit']as $fault){$order=$this->order('APPROVED');$body=$this->body($order);$confirm=$this->confirmed($body,$this->invoke($body));global $wpdb;$filter=static function(string $sql)use($fault):string{if(($fault==='order'&&str_starts_with($sql,'UPDATE `'.Tables::orders().'`'))||($fault==='audit'&&str_starts_with($sql,'INSERT INTO `'.Tables::audit_log().'`')&&str_contains($sql,'portal_order_held')))return 'INSERT INTO missing_hold_effect (id) VALUES (1)';return $sql;};$prior=$wpdb->suppress_errors(true);add_filter('query',$filter);try{$html=$this->invoke($confirm);}finally{remove_filter('query',$filter);$wpdb->suppress_errors($prior);}self::assertStringNotContainsString('Order placed ON_HOLD locally',$html);self::assertSame('APPROVED',$wpdb->get_var($wpdb->prepare('SELECT state FROM '.Tables::orders().' WHERE id=%d',$order)));self::assertStringContainsString('already been accepted',$this->invoke($confirm));}
 }
 public function testOptionalReadinessOutageDoesNotUndoConfirmedRestriction():void {
  self::assertTrue(class_exists(OrderHoldWorkflow::class));$order=$this->order('APPROVED');$body=$this->body($order);$confirm=$this->confirmed($body,$this->invoke($body));global $wpdb;$filter=static fn(string $sql):string=>str_starts_with($sql,'SELECT COUNT(*) FROM '.Tables::order_line_items().' WHERE order_id=')?'SELECT COUNT(*) FROM missing_optional_hold_readiness':$sql;$prior=$wpdb->suppress_errors(true);add_filter('query',$filter);try{$html=$this->invoke($confirm);}finally{remove_filter('query',$filter);$wpdb->suppress_errors($prior);}self::assertStringContainsString('Order placed ON_HOLD locally',$html);self::assertStringContainsString('Readiness: UNAVAILABLE',$html);self::assertStringContainsString('Production ready: NO',$html);self::assertSame('ON_HOLD',$wpdb->get_var($wpdb->prepare('SELECT state FROM '.Tables::orders().' WHERE id=%d',$order)));
 }
 public function testUnexpectedApprovalMutationAndActorLossCannotCommitHold():void {
  self::assertTrue(class_exists(OrderHoldWorkflow::class));foreach(['approval','actor']as $fault){$order=$this->order('APPROVED');$body=$this->body($order);$confirm=$this->confirmed($body,$this->invoke($body));global $wpdb;$actor=wp_get_current_user();$changed=false;$filter=static function(string $sql)use($fault,$actor,&$changed):string{if(!$changed&&str_starts_with($sql,'UPDATE `'.Tables::orders().'`')){$changed=true;if($fault==='approval')$sql=str_replace(' SET ',' SET `approved_by` = 999999, ',$sql);else $actor->add_cap('manage_digiforge_pod',false);}return $sql;};add_filter('query',$filter);try{$html=$this->invoke($confirm);}finally{remove_filter('query',$filter);$actor->add_cap('manage_digiforge_pod');}self::assertTrue($changed);self::assertStringNotContainsString('Order placed ON_HOLD locally',$html);self::assertSame('APPROVED',$wpdb->get_var($wpdb->prepare('SELECT state FROM '.Tables::orders().' WHERE id=%d',$order)));}
 }
 public function testOuterTransactionIsDeniedBeforeAcknowledgement():void {
  self::assertTrue(class_exists(OrderHoldWorkflow::class));$order=$this->order('VALIDATED');$body=$this->body($order);$confirm=$this->confirmed($body,$this->invoke($body));global $wpdb;$before=$wpdb->get_var("SELECT COUNT(*) FROM ".Tables::audit_log()." WHERE event_type='portal_review_confirmation_accepted'");$wpdb->query('START TRANSACTION');try{$html=$this->invoke($confirm);self::assertStringContainsString('clean database transaction boundary',$html);self::assertSame('1',(string)$wpdb->get_var('SELECT @@session.in_transaction'));self::assertSame($before,$wpdb->get_var("SELECT COUNT(*) FROM ".Tables::audit_log()." WHERE event_type='portal_review_confirmation_accepted'"));}finally{$wpdb->query('ROLLBACK');}
 }
 public function testLostTransactionAcknowledgementReportsUnknownInsteadOfFalseRollback():void {
  self::assertTrue(class_exists(OrderHoldWorkflow::class));$order=$this->order('APPROVED');$body=$this->body($order);$confirm=$this->confirmed($body,$this->invoke($body));global $wpdb;$reads=0;$lost=false;$filter=static function(string $sql)use($wpdb,&$reads,&$lost):string{if(str_starts_with($sql,'SELECT CONNECTION_ID() AS connection_id')&&++$reads===2){$wpdb->query('COMMIT');$lost=true;}return $sql;};add_filter('query',$filter);try{$html=$this->invoke($confirm);}finally{remove_filter('query',$filter);}self::assertTrue($lost);self::assertStringContainsString('outcome is UNKNOWN',$html);self::assertStringNotContainsString('Order placed ON_HOLD locally',$html);self::assertSame('ON_HOLD',$wpdb->get_var($wpdb->prepare('SELECT state FROM '.Tables::orders().' WHERE id=%d',$order)));
 }
 private function order(string $state):int {$repo=new Repository();$row=PrintifyApiApprovalFixture::checked($repo->createOrder(['channel'=>'etsy','shop_reference'=>'personalized_pod','environment'=>'test','external_order_reference'=>'local-hold-'.wp_generate_uuid4()]));if($state==='VALIDATED')PrintifyApiApprovalFixture::checked($repo->transition('order',(int)$row['id'],'VALIDATED'));elseif($state!=='RECEIVED'){PrintifyApiApprovalFixture::checked($repo->transition('order',(int)$row['id'],'REVIEW_REQUIRED'));if($state==='APPROVED')PrintifyApiApprovalFixture::checked($repo->transition('order',(int)$row['id'],'APPROVED'));}return (int)$row['id'];}
 private function children():array {[, $mapping,$version,$ownership]=$this->product();$order=$this->order('APPROVED');$repo=new Repository();$line=PrintifyApiApprovalFixture::checked($repo->addLineItem(['order_id'=>$order,'product_version_id'=>$version,'provider_mapping_id'=>$mapping,'quantity'=>2]));$pod=new \DigiForge\POD\Repository();$schema=PrintifyApiApprovalFixture::checked($pod->createPersonalizationSchema(['product_version_id'=>$version,'schema_key'=>'hold-history-input','version_label'=>'v1','field_definitions'=>[['key'=>'name','type'=>'text','required'=>true]]]));foreach(['VALIDATED','REVIEW_REQUIRED','APPROVED']as $state)PrintifyApiApprovalFixture::checked($pod->transition('personalization',(int)$schema['id'],$state));$submission=PrintifyApiApprovalFixture::checked($repo->createPersonalization(['order_line_item_id'=>$line['id'],'personalization_schema_id'=>$schema['id'],'payload'=>['name'=>'Synthetic retained buyer input']]));PrintifyApiApprovalFixture::checked($repo->reviewPersonalization((int)$submission['id'],'APPROVED'));$plan=PrintifyApiApprovalFixture::checked($repo->createPlan(['order_id'=>$order,'provider'=>'printify','shipping_method_metadata'=>['method'=>'standard'],'cost_snapshot_metadata'=>['base_production_cost'=>10,'shipping_estimate'=>4]]));foreach(['REVIEW_REQUIRED','APPROVED']as $state)PrintifyApiApprovalFixture::checked($repo->transition('plan',(int)$plan['id'],$state));PrintifyApiApprovalFixture::checked($repo->createIntent(['order_id'=>$order,'fulfillment_plan_id'=>$plan['id'],'intent_type'=>'PREPARE_FULFILLMENT']));$render=PrintifyApiApprovalFixture::checked((new \DigiForge\POD\RenderEvidenceRepository())->create(['order_id'=>$order,'provider_mapping_id'=>$mapping,'template_key'=>'hold-history-asserted-only','template_version'=>'1','template_sha256'=>hash('sha256','hold-template'),'personalization_evidence_hash'=>$submission['payload_hash'],'output_sha256'=>hash('sha256','asserted-output-only'),'buyer_preview_sha256'=>hash('sha256','asserted-output-only'),'render_mode'=>'DETERMINISTIC']));global $wpdb;
  // Non-authorizing stored package metadata only; restriction must preserve even uncertified history.
  self::assertSame(1,$wpdb->insert(Tables::pod_authorization_packages(),['order_id'=>$order,'render_evidence_id'=>$render['id'],'provider_mapping_id'=>$mapping,'ownership_mapping_id'=>$ownership,'readiness_hash'=>hash('sha256','asserted-readiness'),'package_hash'=>hash('sha256','hold-review-history:'.$order),'state'=>'REVIEW_REQUIRED','external_execution_authorized'=>0,'external_execution_performed'=>0,'created_at'=>current_time('mysql',true)]));$rows=[];foreach([Tables::order_line_items(),Tables::fulfillment_plans(),Tables::fulfillment_intents(),Tables::pod_render_evidence(),Tables::pod_authorization_packages()]as $table)$rows[$table]=$wpdb->get_results($wpdb->prepare('SELECT * FROM '.$table.' WHERE order_id=%d ORDER BY id',$order),ARRAY_A);return [$order,$rows];}
 private function body(int $order):array {return ['action'=>OrderHoldWorkflow::ACTION,'order_id'=>(string)$order,'shop_key'=>'personalized_pod','phase'=>'preview','_wpnonce'=>wp_create_nonce(OrderHoldWorkflow::ACTION.':'.$order),'return_url'=>home_url('/operations/')];}
 private function invoke(array $body):string {$post=$_POST;$had=array_key_exists('REQUEST_METHOD',$_SERVER);$method=$_SERVER['REQUEST_METHOD']??null;$_POST=$body;$_SERVER['REQUEST_METHOD']='POST';ob_start();try{try{do_action('admin_post_'.$body['action']);}catch(WPDieException $e){echo esc_html($e->getMessage());}return (string)ob_get_contents();}finally{ob_end_clean();$_POST=$post;if($had)$_SERVER['REQUEST_METHOD']=$method;else unset($_SERVER['REQUEST_METHOD']);}}
 private function confirmed(array $body,string $html):array {$dom=new DOMDocument();@$dom->loadHTML($html);foreach($dom->getElementsByTagName('input')as $input){$key=$input->getAttribute('name');if($key==='df_confirmation_tokens[REVIEW]')$body['df_confirmation_tokens']['REVIEW']=$input->getAttribute('value');elseif(str_starts_with($key,'df_confirmation_'))$body[$key]=$input->getAttribute('value');}$body['phase']='confirm';$body['df_confirm_review']='1';return $body;}
}
